// ⚠️ 2026-09-04 신규(사장님 지적: "색상이 너무 적다 — 표준색상표를 넣어라") —
// STANDARD_COLOR_PALETTE를 쓰는 공용 색상선택 UI입니다. 처음엔 자주쓰는 색만,
// "더보기"를 누르면 계열별 전체 팔레트를 폅니다. 13개 표준모형 어디서든(배경·
// 선·띠·다각형 영역) 이 컴포넌트 하나만 재사용합니다.
function StandardColorPicker({ value, onPick, label, compact = false }) {
  const [expanded, setExpanded] = React.useState(false);
  const [showGrid, setShowGrid] = React.useState(false);
  // ⚠️ 2026-09-04 신규(사장님+아스트라 확정: "COLOR-001 — 색상값 보존" 원칙,
  // 결제 전 최종안내 논의에서 나온 "정확한 색을 원하면 코드를 직접 입력") —
  // 모든 색상선택기 공통으로 HEX 직접입력을 추가합니다. 여기서 나온 값은
  // 엔진이 "비슷한 색"으로 다시 해석하지 않고 그대로 onPick에 넘깁니다.
  const [hexInput, setHexInput] = React.useState(value || "");
  const [hexError, setHexError] = React.useState(false);
  React.useEffect(() => { setHexInput(value || ""); setHexError(false); }, [value]);
  const submitHex = () => {
    const v = hexInput.trim();
    const normalized = v.startsWith("#") ? v : `#${v}`;
    if (/^#[0-9A-Fa-f]{6}$/.test(normalized)) {
      setHexError(false);
      onPick(normalized.toUpperCase());
    } else {
      setHexError(true);
    }
  };
  const swatchStyle = (hex) => ({
    width: 28, height: 28, borderRadius: "50%", background: hex, cursor: "pointer",
    border: value === hex ? "2px solid var(--ink)" : "1px solid var(--line)",
  });
  // ⚠️ 2026-09-04 추가(사장님 지적: "간격이 좁아서 터치가 힘들 수 있으니 바깥
  // 2칸부터 합쳐라") — 실제 화면폭을 재는 대신, 이 편집화면이 이미 갖고 있는
  // compact(좁은 화면) 여부로 근사합니다. compact면 그리드 각 줄의 양 끝 2칸을
  // 하나로 합치고, 그 칸의 색은 두 원래색의 중간값(HSL 평균)을 씁니다 — 완전히
  // "화면폭에 따라 실시간으로" 합치는 것은 아니라서 정직하게 근사임을 남깁니다.
  const mergeOuterPairs = (row) => {
    if (!compact || row.length < 4) return row;
    const midHex = (a, b) => {
      const toRgb = (h) => [1, 3, 5].map((i) => parseInt(h.slice(i, i + 2), 16));
      const [r1, g1, b1] = toRgb(a.slice(1)), [r2, g2, b2] = toRgb(b.slice(1));
      const mid = (x, y) => Math.round((x + y) / 2).toString(16).padStart(2, "0");
      return `#${mid(r1, r2)}${mid(g1, g2)}${mid(b1, b2)}`.toUpperCase();
    };
    const merged = midHex(row[0], row[1]);
    const mergedEnd = midHex(row[row.length - 2], row[row.length - 1]);
    return [merged, ...row.slice(2, -2), mergedEnd];
  };
  return (
    <div style={{ marginBottom: 8 }}>
      {label && <div style={{ fontSize: 11, color: "var(--ink-soft)", marginBottom: 4 }}>{label}</div>}
      <div style={{ display: "flex", gap: 6, flexWrap: "wrap", alignItems: "center" }}>
        {STANDARD_COLOR_PALETTE.quick.map((hex) => (
          <button key={hex} onClick={() => onPick(hex)} style={swatchStyle(hex)} title={findStandardColorName(hex) || hex} />
        ))}
        <button onClick={() => setExpanded((v) => !v)} style={{
          padding: "4px 8px", borderRadius: 8, border: "1px solid var(--line)", background: "var(--paper-white)",
          cursor: "pointer", fontSize: 10.5, fontFamily: "inherit",
        }}>
          {expanded ? "접기" : "더보기"}
        </button>
      </div>
      {/* ⚠️ COLOR-001: 색상코드 직접입력 — 항상 보이는 위치(더보기 안 눌러도) */}
      <div style={{ display: "flex", gap: 6, alignItems: "center", marginTop: 6 }}>
        <span style={{ fontSize: 10.5, color: "var(--ink-soft)" }}>색상코드</span>
        <input value={hexInput} onChange={(e) => { setHexInput(e.target.value); setHexError(false); }}
          onKeyDown={(e) => { if (e.key === "Enter") submitHex(); }}
          placeholder="#008C95" style={{
            width: 90, padding: "4px 6px", borderRadius: 6, border: hexError ? "1.5px solid #EF4444" : "1px solid var(--line)",
            fontSize: 11, fontFamily: "monospace",
          }} />
        <button onClick={submitHex} style={{
          padding: "3px 8px", borderRadius: 6, border: "1px solid var(--line)", background: "var(--paper-white)",
          cursor: "pointer", fontSize: 10.5, fontFamily: "inherit",
        }}>적용</button>
      </div>
      {hexError && <div style={{ fontSize: 10, color: "#EF4444", marginTop: 3 }}>색상코드를 다시 확인해주세요. 예: #008C95</div>}
      {expanded && (
        <div style={{ marginTop: 8, padding: 8, border: "1px solid var(--line)", borderRadius: 10 }}>
          {STANDARD_COLOR_PALETTE.groups.map((g) => (
            <div key={g.label} style={{ marginBottom: 6 }}>
              <div style={{ fontSize: 10, color: "var(--ink-soft)", marginBottom: 3 }}>{g.label}</div>
              <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
                {g.colors.map((c) => (
                  <button key={c.hex} onClick={() => onPick(c.hex)} style={swatchStyle(c.hex)} title={c.name} />
                ))}
              </div>
            </div>
          ))}
          {/* ⚠️ 2026-09-04 추가(사장님 지적: "일반색상표를 쓸 수 없나요? 색이
              너무 없다") — 색상×명도 그리드(12×5, 고정 HSL 계산)를 폅니다. */}
          <button onClick={() => setShowGrid((v) => !v)} style={{
            marginTop: 6, padding: "4px 8px", borderRadius: 8, border: "1px solid var(--line)",
            background: "var(--paper-white)", cursor: "pointer", fontSize: 10.5, fontFamily: "inherit",
          }}>
            {showGrid ? "일반색상표 접기" : "일반색상표 펼치기"}
          </button>
          {showGrid && (
            <div style={{ marginTop: 6 }}>
              {GENERAL_COLOR_GRID.map((row, ri) => (
                <div key={ri} style={{ display: "flex", gap: 3, marginBottom: 3 }}>
                  {mergeOuterPairs(row).map((hex, ci) => (
                    <button key={ci} onClick={() => onPick(hex)} style={{
                      width: 20, height: 20, borderRadius: 4, background: hex, cursor: "pointer",
                      border: value === hex ? "2px solid var(--ink)" : "1px solid var(--line)", flex: "1 1 0",
                    }} title={hex} />
                  ))}
                </div>
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

// ⚠️ 2026-09-22 수정(사장님 지적: "동그라미 색상표는 이상하다 — 캡처처럼
// 사각 색상표로 해달라, 색에 예민한 분을 위해 코드로도 할 수 있게 해달라") —
// 처음엔 원형(색상환)으로 만들었는데, 사장님이 참고 캡처(선택색 미리보기 막대
// +HEX입력+조회 버튼, 그 아래 사각 스와치 그리드)를 보내며 정정을 요청해서
// 사각형 그리드로 다시 만듭니다. 색 데이터는 그대로 GENERAL_COLOR_GRID(이미
// 검증된 고정 HSL 표)를 재사용하고, 배치만 원형→사각형 그리드로 바꿨습니다.
// value/onPick/label 자리는 이전(ColorWheelPicker)과 동일해서 호출부를 그대로
// 옮겨 쓸 수 있습니다.
function ColorGridPicker({ value, onPick, label }) {
  const [hexInput, setHexInput] = React.useState(value || "");
  const [hexError, setHexError] = React.useState(false);
  React.useEffect(() => { setHexInput(value || ""); setHexError(false); }, [value]);
  const submitHex = () => {
    const v = hexInput.trim();
    const normalized = v.startsWith("#") ? v : `#${v}`;
    if (/^#[0-9A-Fa-f]{6}$/.test(normalized)) { setHexError(false); onPick(normalized.toUpperCase()); }
    else setHexError(true);
  };
  const isSelected = (hex) => value && value.toUpperCase() === hex.toUpperCase();
  // ⚠️ 2026-09-22 수정(사장님 지적 7번 — "색상표가 너무 길어보여요. 흰색박스에
  // 들어갈 수 있도록") — GENERAL_COLOR_GRID가 한 줄에 12칸이라, 이전 15px
  // 칸에서는 한 줄 너비(213px)가 이 컴포넌트의 고정 너비(172px)를 넘어 밖으로
  // 삐져나왔습니다. 칸을 줄여서 12칸이 172px 안에 들어오게 맞췄습니다.
  const CELL = 11;
  const cellStyle = (hex) => ({
    width: CELL, height: CELL, borderRadius: 3, background: hex, padding: 0, cursor: "pointer",
    border: isSelected(hex) ? "2px solid var(--ink)" : "1px solid rgba(0,0,0,0.12)",
    boxSizing: "border-box",
  });
  // 첫 줄 — 자주 쓰는 뚜렷한 색(흰색·검정 포함, 그리드엔 없는 무채색 보완).
  const quickRow = STANDARD_COLOR_PALETTE.quick;
  return (
    <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 6, width: 172 }}>
      {label && <div style={{ fontSize: 11, fontWeight: 700, color: "var(--ink)" }}>{label}</div>}
      {/* 선택색 미리보기 막대 + HEX입력 + 조회 버튼 — 참고 캡처와 같은 구성. */}
      <div style={{ display: "flex", gap: 4, width: "100%" }}>
        <div style={{ flex: 1, height: 26, borderRadius: 6, background: value || "#FFFFFF", border: "1px solid var(--line)" }} />
        <input value={hexInput} onChange={(e) => { setHexInput(e.target.value); setHexError(false); }}
          onKeyDown={(e) => { if (e.key === "Enter") submitHex(); }}
          placeholder="#008C95" style={{
            width: 72, padding: "4px 5px", borderRadius: 6, textAlign: "center",
            border: hexError ? "1.5px solid #EF4444" : "1px solid var(--line)", fontSize: 10.5, fontFamily: "monospace",
          }} />
        <button type="button" onClick={submitHex} style={{
          padding: "3px 7px", borderRadius: 6, border: "1px solid var(--line)", background: "var(--paper-white)",
          cursor: "pointer", fontSize: 10, fontFamily: "inherit", flexShrink: 0,
        }}>조회</button>
      </div>
      {hexError && <div style={{ fontSize: 10, color: "#EF4444" }}>색상코드를 확인해주세요. 예: #008C95</div>}
      <div style={{ fontSize: 10.5, fontFamily: "monospace", color: "var(--ink-soft)" }}>선택색 {value || "-"}</div>
      {/* 사각 색상표 — 첫 줄(자주 쓰는 색) + GENERAL_COLOR_GRID(12색상×5명도). */}
      <div style={{ display: "flex", flexDirection: "column", gap: 2 }}>
        <div style={{ display: "flex", gap: 2, flexWrap: "wrap", justifyContent: "center" }}>
          {quickRow.map((hex) => <button key={hex} type="button" onClick={() => onPick(hex)} title={hex} style={cellStyle(hex)} />)}
        </div>
        {GENERAL_COLOR_GRID.map((row, ri) => (
          <div key={ri} style={{ display: "flex", gap: 2 }}>
            {row.map((hex, ci) => <button key={ci} type="button" onClick={() => onPick(hex)} title={hex} style={cellStyle(hex)} />)}
          </div>
        ))}
      </div>
    </div>
  );
}

// "수정하고싶어요"에서 텍스트 항목을 골랐을 때, 지금 화면 위치는 그대로 두고 그
// 항목만 바로 고쳐서 저장하는 작은 편집창(2026-09-03, 사장님 신고 반영).
function QuickEditPanel({ label, initialValue, onSave, onCancel, formatValue, multiline }) {
  const [val, setVal] = useState(initialValue || "");
  const InputTag = multiline ? "textarea" : "input";
  return (
    <div>
      <div style={{ fontSize: 14, fontWeight: 700, color: "var(--ink)", marginBottom: 12 }}>{label} 수정</div>
      <InputTag
        autoFocus value={val} onChange={(e) => setVal(formatValue ? formatValue(e.target.value) : e.target.value)}
        onKeyDown={(e) => { if (e.key === "Enter" && !multiline && val.trim()) onSave(val.trim()); }}
        style={{
          width: "100%", border: "1.5px solid var(--line)", borderRadius: 10, padding: "10px 12px",
          fontSize: 13, fontFamily: "inherit", background: "var(--paper-white)", color: "var(--ink)",
          marginBottom: 10, boxSizing: "border-box",
          ...(multiline ? { minHeight: 78, resize: "vertical", lineHeight: 1.5 } : {}),
        }}
      />
      <div style={{ display: "flex", gap: 8 }}>
        <button onClick={onCancel} style={{
          flex: 1, background: "none", border: "1.5px solid var(--line)", borderRadius: 10,
          padding: "10px 0", fontSize: 13, fontWeight: 700, color: "var(--ink-soft)",
          cursor: "pointer", fontFamily: "inherit",
        }}>취소</button>
        <button disabled={!val.trim()} onClick={() => onSave(val.trim())} style={{
          flex: 1, background: "var(--stamp)", border: "none", borderRadius: 10,
          padding: "10px 0", fontSize: 13, fontWeight: 700, color: "#fff",
          cursor: val.trim() ? "pointer" : "default", opacity: val.trim() ? 1 : 0.5, fontFamily: "inherit",
        }}>저장</button>
      </div>
    </div>
  );
}

function ChatConfirmCard({ title, rows, onApply, onRetry, applyLabel = "이대로 적용", retryLabel = "다시 말할게요" }) {
  return (
    <div style={{ marginBottom: 14 }}>
      <div style={{
        background: "var(--paper-white)", border: "1.5px solid var(--line)", borderRadius: 12,
        padding: "13px 15px", marginBottom: 8,
      }}>
        <div style={{ fontSize: 12, fontWeight: 700, color: "var(--stamp)", marginBottom: 8 }}>{title}</div>
        {rows.map((r) => (
          <div key={r.k} style={{ display: "flex", justifyContent: "space-between", fontSize: 12.5, padding: "4px 0", gap: 10 }}>
            <span style={{ color: "var(--ink-soft)", flexShrink: 0 }}>{r.k}</span>
            <span style={{ fontWeight: 600, color: "var(--ink)", textAlign: "right" }}>{r.v}</span>
          </div>
        ))}
      </div>
      <div style={{ display: "flex", gap: 8 }}>
        <button onClick={onApply} style={{
          flex: 1, background: "var(--stamp)", border: "none", color: "#fff", borderRadius: 10,
          fontSize: 13, fontWeight: 700, padding: "11px 0", cursor: "pointer", fontFamily: "inherit",
        }}>{applyLabel}</button>
        {onRetry && (
          <button onClick={onRetry} style={{
            flex: 1, background: "var(--paper-white)", border: "1.5px solid var(--line)", color: "var(--ink)",
            borderRadius: 10, fontSize: 13, fontWeight: 700, padding: "11px 0", cursor: "pointer", fontFamily: "inherit",
          }}>{retryLabel}</button>
        )}
      </div>
    </div>
  );
}

// 전화번호 입력칸에서 숫자만 쳐도 자동으로 하이픈(-)을 넣어줍니다. 010 등
// 휴대폰과 지역번호(02는 2자리, 나머지는 3자리)를 구분해서 자릿수를 맞춥니다.
function formatPhoneInput(raw) {
  const digits = raw.replace(/[^0-9]/g, "").slice(0, 11);
  if (digits.length < 4) return digits;
  if (digits.startsWith("02")) {
    if (digits.length <= 5) return `${digits.slice(0, 2)}-${digits.slice(2)}`;
    if (digits.length <= 9) return `${digits.slice(0, 2)}-${digits.slice(2, 5)}-${digits.slice(5)}`;
    return `${digits.slice(0, 2)}-${digits.slice(2, 6)}-${digits.slice(6, 10)}`;
  }
  if (digits.length <= 7) return `${digits.slice(0, 3)}-${digits.slice(3)}`;
  if (digits.length <= 10) return `${digits.slice(0, 3)}-${digits.slice(3, 6)}-${digits.slice(6)}`;
  return `${digits.slice(0, 3)}-${digits.slice(3, 7)}-${digits.slice(7, 11)}`;
}

function ChatTextComposer({ placeholder, onSubmit, onSkip, skipLabel, disabled, initialValue, needsReview, formatValue, multiline, onEnglish }) {
  const [val, setVal] = useState(initialValue || "");
  const [englishHint, setEnglishHint] = useState(false);
  const submit = () => {
    if (disabled || !val.trim()) return;
    onSubmit(val.trim());
    setVal("");
  };
  // 2026-09-22 추가 — introText(소개문구)처럼 고객이 직접 줄바꿈을 넣어야 하는
  // 필드용. 기존 input과 동작이 다른 점: Enter가 제출이 아니라 줄바꿈이고(그래서
  // "확인" 버튼을 눌러야 제출), textarea를 씁니다. 그 외(placeholder/onSkip/
  // formatValue 등)는 전부 동일 — 다른 모든 필드의 기존 동작은 안 건드립니다.
  const InputTag = multiline ? "textarea" : "input";
  return (
    <div style={{ marginBottom: 14 }}>
      {needsReview && (
        <div style={{ fontSize: 11, color: "var(--stamp)", fontWeight: 700, marginBottom: 6 }}>
          ⚠️ 사진에서 읽은 예시 값이에요 — 실제와 다르면 직접 고쳐주세요
        </div>
      )}
      <InputTag
        disabled={disabled}
        style={{
          width: "100%", border: `1.5px solid ${needsReview ? "var(--stamp)" : "var(--line)"}`, borderRadius: 10, padding: "10px 12px",
          fontSize: 13, fontFamily: "inherit", background: disabled ? "var(--paper-deep)" : "var(--paper-white)",
          color: "var(--ink)", opacity: disabled ? 0.6 : 1, marginBottom: 8, boxSizing: "border-box",
          ...(multiline ? { minHeight: 78, resize: "vertical", lineHeight: 1.5 } : {}),
        }}
        placeholder={placeholder} value={val} autoFocus
        onChange={(e) => setVal(formatValue ? formatValue(e.target.value) : e.target.value)}
        onKeyDown={(e) => {
          if (e.key !== "Enter" || e.nativeEvent?.isComposing) return;
          // 2026-10-01 — 아무것도 안 쓰고 엔터 = 건너뛰기(건너뛸 수 있는 칸만). 여러 줄 칸은
          // 글자가 있을 때 엔터가 줄바꿈이라 [확인]으로 제출합니다.
          if (!val.trim()) { if (onSkip && !disabled) { e.preventDefault(); onSkip(); } return; }
          if (!multiline) submit();
        }}
      />
      <div style={{ display: "flex", gap: 8 }}>
        {onSkip && (
          <button disabled={disabled} onClick={onSkip} style={{
            flex: 1, background: "var(--paper-white)", border: "1.5px solid var(--line)", color: "var(--ink-soft)",
            borderRadius: 10, padding: "10px 0", fontSize: 13, fontWeight: 700,
            cursor: disabled ? "default" : "pointer", fontFamily: "inherit", opacity: disabled ? 0.6 : 1,
          }}>{skipLabel || "생략"}</button>
        )}
        {onEnglish && (
          // 2026-10-01 — [확인] 옆 [영문입력]: 한글을 먼저 입력해야 눌림(빈 칸이면 안내만).
          <button disabled={disabled} onClick={() => { if (!val.trim()) { setEnglishHint(true); return; } onEnglish(val.trim()); setVal(""); }} style={{
            flex: 1, background: "var(--paper-white)", border: "1.5px solid var(--stamp)", color: "var(--stamp)",
            borderRadius: 10, padding: "10px 0", fontSize: 13, fontWeight: 700,
            cursor: disabled ? "default" : "pointer", fontFamily: "inherit", opacity: disabled ? 0.6 : 1,
          }}>영문입력</button>
        )}
        <button disabled={disabled} onClick={submit} style={{
          flex: 1, background: "var(--stamp)", border: "none", color: "#fff", borderRadius: 10,
          padding: "10px 0", fontSize: 13, fontWeight: 700, cursor: disabled ? "default" : "pointer",
          fontFamily: "inherit", opacity: disabled ? 0.6 : 1,
        }}>확인</button>
      </div>
      {englishHint && !val.trim() && <div style={{ fontSize: 11, color: "var(--ink-soft)", marginTop: 6 }}>한글을 먼저 입력한 뒤 [영문입력]을 눌러주세요.</div>}
    </div>
  );
}

function ChatUploadBox({ onFile, accept = "image/*", mode = "both" }) {
  const cameraRef = React.useRef(null);
  const fileRef = React.useRef(null);
  return (
    <div style={{ marginBottom: 14 }}>
      <input ref={cameraRef} type="file" accept={accept} capture="environment" style={{ display: "none" }}
        onChange={(e) => { const f = e.target.files?.[0]; if (f) onFile(f); }} />
      <input ref={fileRef} type="file" accept={accept} style={{ display: "none" }}
        onChange={(e) => { const f = e.target.files?.[0]; if (f) onFile(f); }} />
      <div style={{ display: "flex", gap: 8 }}>
        {mode !== "file" && (
          <button onClick={() => cameraRef.current?.click()} style={{
            flex: 1, border: "1.5px dashed var(--line)", borderRadius: 12, padding: "22px 12px",
            background: "var(--paper-deep)", color: "var(--ink-soft)", fontSize: 12.5, fontWeight: 600,
            cursor: "pointer", fontFamily: "inherit", display: "flex", flexDirection: "column",
            alignItems: "center", gap: 6,
          }}>
            <Camera size={18} />
            촬영하기
          </button>
        )}
        {mode !== "camera" && (
          <button onClick={() => fileRef.current?.click()} style={{
            flex: 1, border: "1.5px dashed var(--line)", borderRadius: 12, padding: "22px 12px",
            background: "var(--paper-deep)", color: "var(--ink-soft)", fontSize: 12.5, fontWeight: 600,
            cursor: "pointer", fontFamily: "inherit", display: "flex", flexDirection: "column",
            alignItems: "center", gap: 6,
          }}>
            <Upload size={18} />
            파일 올리기
          </button>
        )}
      </div>
    </div>
  );
}

const CHAT_STATUS_LABEL = { DRAFT: "작성중", PREVIEW: "미리보기", CONFIRMED: "확정" };

// ⚠️ 2026-09-02 추가 — "AI 무료혜택은 주문이 아니라 고객 사용이력에 붙어야 한다"
// 원칙(사장님+쳇 확정)의 화면단계 흉내. 진짜 방어(계정 간 공유, 여러 브라우저,
// 로그아웃-재가입 등)는 서버·DB가 있어야 완성되고, 이건 그때까지의 임시 장치일
// 뿐입니다 — 브라우저를 지우거나 다른 기기로 오면 이 기록은 못 봅니다. 휴대폰
// 번호(로그인 식별자, 명함 내용용 연락처와는 다른 값)를 키로 씁니다.
function aiUsageStorageKey(phone) {
  const digits = (phone || "").replace(/[^0-9]/g, "");
  return `bizcard_ai_usage:${digits}`;
}
function loadAiUsageRecord(phone) {
  if (!phone) return null;
  try {
    const raw = localStorage.getItem(aiUsageStorageKey(phone));
    return raw ? JSON.parse(raw) : null;
  } catch {
    return null;
  }
}
function saveAiUsageRecord(phone, patchObj) {
  if (!phone) return;
  try {
    const current = loadAiUsageRecord(phone) || {};
    localStorage.setItem(aiUsageStorageKey(phone), JSON.stringify({ ...current, ...patchObj }));
  } catch {
    // 저장 실패해도 이번 세션 진행은 막지 않음
  }
}

// ⚠️ 2026-09-04 추가(사장님 지적: "이어서 작업하기"가 실제로는 아무것도 안 불러왔음) —
// 같은 기기·브라우저 안에서 "이어서 작업"을 실제로 구현합니다. 서버 저장 없이도
// 가능한 부분(브라우저 localStorage)까지만 하고, 다른 기기에서 불러오는 건 여전히
// 서버가 있어야 합니다(그건 안 함, 정직하게 이번 범위 밖). 로고파일·사진파일 같은
// 실제 업로드 File 객체는 localStorage에 못 넣으므로(용량·직렬화 문제) 복원 대상이
// 아닙니다 — 텍스트/선택값만 복원하고, 파일이 필요한 단계는 다시 올리게 안내합니다.
function designProgressStorageKey(phone) {
  const digits = (phone || "").replace(/[^0-9]/g, "");
  return `bizcard_design_progress:${digits}`;
}
function saveDesignProgress(phone, snapshot) {
  if (!phone) return;
  try {
    localStorage.setItem(designProgressStorageKey(phone), JSON.stringify(snapshot));
  } catch {
    // 저장 실패해도 진행은 막지 않음
  }
}
function loadDesignProgress(phone) {
  if (!phone) return null;
  try {
    const raw = localStorage.getItem(designProgressStorageKey(phone));
    return raw ? JSON.parse(raw) : null;
  } catch {
    return null;
  }
}
// 저장된 스냅샷에 "이어갈 만한" 내용이 실제로 있는지 — companyName 하나가 아니라
// 기본정보 필드 중 뭐라도 있으면 됩니다(2026-09-04 확정, 위 hasSavableProgress와 같은 기준).
function designProgressHasContent(saved) {
  return !!(saved && (saved.companyName || saved.personName || saved.phone || saved.address || saved.telephone || saved.email || saved.website || saved.etcInfo));
}
function clearDesignProgress(phone) {
  if (!phone) return;
  try {
    localStorage.removeItem(designProgressStorageKey(phone));
  } catch {
    // 무시
  }
}

// ⚠️ 2026-09-03 추가(쳇 제안 ①) — 실제 AI 없이도 가능한 "진짜" 기능입니다: 캔버스로
// 이미지 픽셀의 평균색을 뽑아내는 건 이미지처리일 뿐 AI가 아니라서, 지금 단계에서도
// 정확하게 동작합니다. 투명 배경 로고는 알파값 낮은 픽셀을 제외하고 계산합니다.
async function extractAverageColorFromImageFile(file) {
  return new Promise((resolve) => {
    if (!file?.type?.startsWith("image/")) { resolve(null); return; }
    const img = new Image();
    const reader = new FileReader();
    reader.onload = () => { img.src = reader.result; };
    reader.onerror = () => resolve(null);
    img.onload = () => {
      try {
        const canvas = document.createElement("canvas");
        const w = (canvas.width = 32);
        const h = (canvas.height = 32);
        const ctx = canvas.getContext("2d");
        ctx.drawImage(img, 0, 0, w, h);
        const data = ctx.getImageData(0, 0, w, h).data;
        let r = 0, g = 0, b = 0, count = 0;
        for (let i = 0; i < data.length; i += 4) {
          if (data[i + 3] < 100) continue; // 투명 픽셀 제외
          r += data[i]; g += data[i + 1]; b += data[i + 2]; count++;
        }
        if (count === 0) { resolve(null); return; }
        r = Math.round(r / count); g = Math.round(g / count); b = Math.round(b / count);
        resolve(`#${[r, g, b].map((v) => v.toString(16).padStart(2, "0")).join("")}`);
      } catch {
        resolve(null);
      }
    };
    img.onerror = () => resolve(null);
    reader.readAsDataURL(file);
  });
}

// ==================== domain/company/logoBackground ====================
// ⚠️ 2026-09-30 신규(대표님 확정 — "투명배경이 아닌 로고는 흰 박스째 들어간다") —
// 업로드한 로고의 "배경만" 투명하게 만드는 기능입니다. 확정 원칙:
//  ① 로고 자체의 색은 절대 바꾸지 않습니다(흰색 반전 등 금지 — 고객 승낙 없는
//     로고 색 변경 금지). 바뀌는 건 배경 픽셀의 투명도뿐입니다.
//  ② 자동으로 적용하지 않습니다. 처리 전/후를 보여주고 고객이 직접 고릅니다
//     ("투명 배경으로" / "원본 그대로"). 원본을 고르면 파일을 전혀 건드리지 않습니다.
//  ③ 로고 바깥의 빈 여백은 잘라냅니다(투명 처리를 고른 경우와 원래 투명한 로고만).
//     엔진이 이미지 사각형 전체를 로고 크기로 계산하기 때문에, 여백이 남아 있으면
//     실제 로고가 원본 표준모형보다 작고 안쪽으로 밀려 보입니다("잉크 기준" 원칙).
// 방식: 테두리 픽셀로 배경색을 판정하고, 배경색과 가까운 색을 이미지 전체에서
// 투명하게 합니다(테두리에서 이어진 부분만 지우면 '성'·'화'의 ㅇ 안쪽처럼 둘러싸인
// 배경이 흰색으로 남는 것을 시험으로 확인해서 전체 방식을 씁니다). 경계 픽셀은
// 부분 투명 + 배경색 성분 제거로 처리해서 청록 같은 색 위에서도 흰 테두리가 안
// 남게 합니다. 테두리 색이 한 가지가 아니면(사진·그라데이션 배경) 자동 처리를
// 하지 않고 "원본 그대로 / 다시 올리기"만 안내합니다(억지로 지우지 않음).
const LOGO_BG_RULES = {
  transparentBorderAlpha: 10,   // 테두리 픽셀 알파가 이보다 작으면 "이미 투명"
  transparentBorderShare: 0.9,  // 테두리의 90% 이상이 투명이면 투명 로고로 판정
  uniformTol: 40,               // 테두리 색이 배경색과 이 거리 안이면 "같은 배경색"
  uniformShare: 0.6,            // 테두리의 60% 이상이 같은 색이면 자동 처리 후보(2026-10-01: 로고가 이미지 가장자리에 닿게 꽉 잘린 파일은 테두리의 약 26%가 로고라서 90% 기준이면 흰 배경인데도 '복잡한 배경'으로 잘못 판정됐음. 결과는 항상 처리 전/후 비교 후 고객이 고르므로 기준을 낮춰도 고객 모르게 바뀌는 일은 없음)
  keyInnerTol: 15,              // 배경색과 거리 15 이하 → 완전 투명
  keyOuterTol: 60,              // 거리 60 이상 → 완전 불투명(그 사이는 부분 투명)
  trimAlpha: 16,                // 여백 자르기 기준 알파
  maxSidePx: 2000,              // 처리 해상도 상한(더 크면 비율 유지 축소 — 명함 로고 최대폭(카드 42%, 약 38mm)에 넣어도 1300dpi 이상이라 인쇄 품질 영향 없음)
};

function logoColorDistance(r, g, b, bg) {
  return Math.abs(r - bg[0]) + Math.abs(g - bg[1]) + Math.abs(b - bg[2]);
}

function analyzeLogoPixels(data, w, h, rules = LOGO_BG_RULES) {
  // 1) 테두리 픽셀 수집
  const border = [];
  const pushPx = (x, y) => { const i = (y * w + x) * 4; border.push([data[i], data[i + 1], data[i + 2], data[i + 3]]); };
  for (let x = 0; x < w; x++) { pushPx(x, 0); if (h > 1) pushPx(x, h - 1); }
  for (let y = 1; y < h - 1; y++) { pushPx(0, y); if (w > 1) pushPx(w - 1, y); }
  const transparentShare = border.filter((p) => p[3] < rules.transparentBorderAlpha).length / border.length;
  let kind, bgColor = null, out;
  if (transparentShare >= rules.transparentBorderShare) {
    kind = "transparent";
    out = new Uint8ClampedArray(data);
  } else {
    const opaque = border.filter((p) => p[3] >= rules.transparentBorderAlpha);
    const median = (arr) => { const s = [...arr].sort((a, b) => a - b); return s[Math.floor(s.length / 2)]; };
    bgColor = [0, 1, 2].map((c) => median(opaque.map((p) => p[c])));
    const uniform = opaque.filter((p) => logoColorDistance(p[0], p[1], p[2], bgColor) <= rules.uniformTol).length / Math.max(1, opaque.length);
    if (uniform < rules.uniformShare) {
      return { kind: "complex", bgColor, out: null, bbox: null, inkColors: [] };
    }
    kind = "solid";
    out = new Uint8ClampedArray(data.length);
    const span = rules.keyOuterTol - rules.keyInnerTol;
    for (let i = 0; i < data.length; i += 4) {
      const r = data[i], g = data[i + 1], b = data[i + 2], a0 = data[i + 3];
      const d = logoColorDistance(r, g, b, bgColor);
      const k = Math.max(0, Math.min(1, (d - rules.keyInnerTol) / span));
      if (k <= 0) { out[i + 3] = 0; continue; }
      if (k < 1) {
        // 경계 픽셀: 관측색 = k·로고색 + (1-k)·배경색 → 로고색만 복원(배경색 성분 제거)
        out[i] = Math.round(Math.max(0, Math.min(255, (r - (1 - k) * bgColor[0]) / k)));
        out[i + 1] = Math.round(Math.max(0, Math.min(255, (g - (1 - k) * bgColor[1]) / k)));
        out[i + 2] = Math.round(Math.max(0, Math.min(255, (b - (1 - k) * bgColor[2]) / k)));
      } else { out[i] = r; out[i + 1] = g; out[i + 2] = b; }
      out[i + 3] = Math.round(a0 * k);
    }
  }
  // 2) 잉크(보이는 부분) 경계 — 여백 자르기용
  let minX = w, minY = h, maxX = -1, maxY = -1;
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) {
    if (out[(y * w + x) * 4 + 3] > rules.trimAlpha) { if (x < minX) minX = x; if (x > maxX) maxX = x; if (y < minY) minY = y; if (y > maxY) maxY = y; }
  }
  const bbox = maxX < 0 ? null : { x: minX, y: minY, w: maxX - minX + 1, h: maxY - minY + 1 };
  // 3) 로고 주요 색(색 겹침 경고용) — 거의 불투명한 픽셀만, 16단계 양자화 후 비중순
  const buckets = new Map(); let total = 0;
  for (let i = 0; i < out.length; i += 4) {
    if (out[i + 3] < 128) continue;
    const key = ((out[i] >> 4) << 8) | ((out[i + 1] >> 4) << 4) | (out[i + 2] >> 4);
    const bk = buckets.get(key) || { r: 0, g: 0, b: 0, n: 0 };
    bk.r += out[i]; bk.g += out[i + 1]; bk.b += out[i + 2]; bk.n++; buckets.set(key, bk); total++;
  }
  const toHex = (v) => Math.round(v).toString(16).padStart(2, "0");
  const inkColors = [...buckets.values()].sort((a, b) => b.n - a.n).slice(0, 8)
    .map((bk) => ({ hex: `#${toHex(bk.r / bk.n)}${toHex(bk.g / bk.n)}${toHex(bk.b / bk.n)}`, weight: bk.n / total }));
  return { kind, bgColor, out, bbox, inkColors };
}

// 브라우저 전용 — 파일을 읽어 analyzeLogoPixels를 돌리고, 투명 처리+여백 자른 PNG
// 파일을 만들어 돌려줍니다. 원본 파일은 그대로 둡니다(고객이 원본을 고를 수 있게).
async function processLogoFile(file, rules = LOGO_BG_RULES) {
  if (!file?.type?.startsWith("image/")) return { kind: "unsupported" };
  const url = await new Promise((resolve, reject) => { const r = new FileReader(); r.onload = () => resolve(r.result); r.onerror = reject; r.readAsDataURL(file); });
  const img = await new Promise((resolve, reject) => { const im = new Image(); im.onload = () => resolve(im); im.onerror = reject; im.src = url; });
  const scale = Math.min(1, rules.maxSidePx / Math.max(img.naturalWidth, img.naturalHeight));
  const w = Math.max(1, Math.round(img.naturalWidth * scale)), h = Math.max(1, Math.round(img.naturalHeight * scale));
  const canvas = document.createElement("canvas"); canvas.width = w; canvas.height = h;
  const ctx = canvas.getContext("2d"); ctx.drawImage(img, 0, 0, w, h);
  const src = ctx.getImageData(0, 0, w, h);
  const result = analyzeLogoPixels(src.data, w, h, rules);
  if (result.kind === "complex" || !result.bbox) return { kind: result.kind === "complex" ? "complex" : "empty", bgColor: result.bgColor, originalUrl: url };
  ctx.putImageData(new ImageData(result.out, w, h), 0, 0);
  const crop = document.createElement("canvas"); crop.width = result.bbox.w; crop.height = result.bbox.h;
  crop.getContext("2d").drawImage(canvas, result.bbox.x, result.bbox.y, result.bbox.w, result.bbox.h, 0, 0, result.bbox.w, result.bbox.h);
  const blob = await new Promise((resolve) => crop.toBlob(resolve, "image/png"));
  const baseName = (file.name || "logo").replace(/\.[^.]+$/, "");
  const processedFile = new File([blob], `${baseName}_투명배경.png`, { type: "image/png" });
  processedFile.__bizcardProcessed = true; // 이 파일이 처리본임을 표시(원본 재처리용)
  return { kind: result.kind, bgColor: result.bgColor, originalUrl: url, processedFile, processedUrl: crop.toDataURL("image/png"), inkColors: result.inkColors };
}

// ---- 색 겹침 경고(대표님 확정 — "막지 말고 경고, 고객이 원하면 그대로") ----
function hexToRgb(hex) {
  const m = /^#?([0-9a-f]{6})$/i.exec(String(hex || "").trim());
  if (!m) return null;
  const n = parseInt(m[1], 16); return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}
function relativeLuminanceRgb([r, g, b]) {
  const f = (v) => { v /= 255; return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); };
  return 0.2126 * f(r) + 0.7152 * f(g) + 0.0722 * f(b);
}
function contrastRatioHex(a, b) {
  const ra = hexToRgb(a), rb = hexToRgb(b); if (!ra || !rb) return null;
  const la = relativeLuminanceRgb(ra), lb = relativeLuminanceRgb(rb);
  return (Math.max(la, lb) + 0.05) / (Math.min(la, lb) + 0.05);
}
function mixHex(a, b, t) {
  const ra = hexToRgb(a), rb = hexToRgb(b); if (!ra || !rb) return a || b;
  const c = ra.map((v, i) => Math.round(v + (rb[i] - v) * t));
  return `#${c.map((v) => v.toString(16).padStart(2, "0")).join("")}`;
}
// 로고 상자 안 25개 지점의 "실제로 깔리는 색"(배경 → 띠/도형 순서, buildCardSVG와
// 같은 좌표 규칙)을 구합니다. 사진 배경은 색을 알 수 없어 null(검사 안 함).
function colorsUnderBoxMm(box, spec, bg, decorations = []) {
  if (bg.backgroundStyle === "photo") return null;
  const workingW = spec.trimWidth + spec.bleed * 2, workingH = spec.trimHeight + spec.bleed * 2;
  const safeX = spec.bleed + spec.safeMargin, safeY = safeX;
  const safeW = spec.trimWidth - spec.safeMargin * 2, safeH = spec.trimHeight - spec.safeMargin * 2;
  const solid = (c) => (typeof c === "object" && c?.from ? mixHex(c.from, c.to, 0.5) : (c || "#ECECF3"));
  const baseAt = (x, y) => {
    if (bg.backgroundStyle === "gradient") {
      const c1 = bg.backgroundAccentColor || "#6C4CF0";
      const c2 = bg.backgroundGradientTo || (bg.backgroundAccentColor ? lightenHex(bg.backgroundAccentColor, 70) : "#4C6FFF");
      const t = bg.backgroundGradientDirection === "leftToRight" ? x / workingW : y / workingH;
      return mixHex(c1, c2, Math.max(0, Math.min(1, t)));
    }
    if (bg.backgroundStyle === "custom" && bg.backgroundAccentColor) return bg.backgroundAccentColor;
    return bg.backgroundStyle === "soft" ? "#F4F1FB" : "#FFFFFF";
  };
  const inPolygon = (x, y, pts) => {
    let inside = false;
    for (let i = 0, j = pts.length - 1; i < pts.length; j = i++) {
      const [xi, yi] = pts[i], [xj, yj] = pts[j];
      if ((yi > y) !== (yj > y) && x < ((xj - xi) * (y - yi)) / (yj - yi) + xi) inside = !inside;
    }
    return inside;
  };
  const colorAt = (x, y) => {
    let c = baseAt(x, y);
    decorations.forEach((d) => {
      if (d.kind === "band") {
        const isH = d.orientation === "horizontal";
        const at = d.fullBleed ? (d.atPercent / 100) * (isH ? workingH : workingW) : (isH ? safeY + (d.atPercent / 100) * safeH : safeX + (d.atPercent / 100) * safeW);
        const wd = d.fullBleed ? (d.widthPercent / 100) * (isH ? workingH : workingW) : (d.widthPercent / 100) * (isH ? safeH : safeW);
        const v = isH ? y : x;
        if (v >= at && v <= at + wd) c = solid(d.color);
      } else if (d.kind === "polygon" && Array.isArray(d.points)) {
        const pts = d.points.map(([px, py]) => [(px / 100) * workingW, (py / 100) * workingH]);
        if (inPolygon(x, y, pts)) c = solid(d.color);
      }
    });
    return c;
  };
  const out = [];
  for (let iy = 0; iy < 5; iy++) for (let ix = 0; ix < 5; ix++) {
    out.push(colorAt(box.boxX + box.widthMm * (0.1 + 0.2 * ix), box.boxY + box.heightMm * (0.1 + 0.2 * iy)));
  }
  return out;
}
// 로고 주요 색 중 "깔리는 색과 명암비 2.0 미만"인 비중을 25개 지점 평균으로 계산,
// 20% 이상이면 경고(진행은 막지 않음). 실제 브라우저 미리보기로 확인한 값(R3 청록
// #0e7c6e 위): AI DESIGN 로고 회색 글자 1.12 → 거의 안 보임, 삼성화재 짙은 파랑 1.91
// → 보이긴 하지만 흐릿함, 로고색=배경색 1.00 → 안 보임. 셋 다 고객이 알고 결정할
// 만한 수준이라 2.0으로 잡았습니다(검정 글자 3.40은 경고 안 함). 20%는 글자 부분처럼
// 면적은 작아도 중요한 부분이 안 보이는 경우까지 잡기 위한 값입니다.
const LOGO_CONTRAST_RULES = { lowRatio: 2.0, warnShare: 0.2 };
function logoLowContrastShare(inkColors, underColors, rules = LOGO_CONTRAST_RULES) {
  if (!inkColors?.length || !underColors?.length) return 0;
  const shares = underColors.map((under) => inkColors.reduce((s, ink) => {
    const r = contrastRatioHex(ink.hex, under); return s + (r != null && r < rules.lowRatio ? ink.weight : 0);
  }, 0) / inkColors.reduce((s, ink) => s + ink.weight, 0));
  return shares.reduce((a, b) => a + b, 0) / shares.length;
}

// AI 신규제작 로고에서 고른 색상 이름을 배경 그라데이션용 hex로 매핑 — "직접 입력"이나
// "AI에게 맡길게요"는 정확한 색을 알 수 없어서 매핑하지 않습니다(억지로 추측 안 함).
const NAMED_LOGO_COLOR_HEX = { "남색": "#1F3A5F", "레드": "#C0392B", "그린": "#2E7D53", "골드": "#B8860B", "블랙": "#1A1A22" };

// ⚠️ 테스트 전용 분류기(2026-09-04, 쳇+사장님 확정) — "OCR이 뱉어낸 원문 텍스트를
// 우리 9개 필드로 분류하는 규칙"만 먼저 실험해보기 위한 함수입니다. 예전 자유입력용
// extractFieldsFromFreeText()(사람이 타이핑한 정돈된 문장 대상, 이미 삭제됨)를
// 되살린 게 아니라 별도로 새로 만들었습니다 — OCR 원문은 줄바꿈·오인식·특수문자
// 깨짐이 섞이기 때문입니다. 회사명·이름·주소는 정규식만으로는 안전하게 못 잡아서
// 후보에 안 넣습니다(엉뚱하게 잘라내는 것보다 고객이 직접 넣는 게 안전 — 오늘 이미
// 확인된 한계입니다, 아래 getMockOcrResult 주석 참고). "기타"는 자동 확정하지
// 않고, 다른 필드에 안 걸린 줄을 전부 후보로 모아서 고객이 추리게 합니다.
function extractFieldsFromOcrText(rawText) {
  const lines = rawText.replace(/\r/g, "").split("\n").map((l) => l.trim()).filter(Boolean);
  const result = { mobile: "", telephone: "", email: "", website: "", position: "", etcCandidates: [] };
  const usedIdx = new Set();
  // OCR에서 흔한 오인식 보정: 숫자 자리에 낀 O/o를 0으로(전화번호류에만 적용,
  // 이메일 등 다른 문맥은 안 건드림)
  const fixDigits = (s) => s.replace(/[Oo](?=[\d\-.\s]*\d)/g, "0");
  const POSITION_KEYWORDS = ["대표", "팀장", "과장", "부장", "이사", "실장", "사원", "대리", "차장", "사장", "전무", "상무", "주임", "매니저"];

  lines.forEach((line, idx) => {
    const fixed = fixDigits(line);
    const mobileMatch = fixed.match(/01[016789][-.\s]?\d{3,4}[-.\s]?\d{4}/);
    if (mobileMatch && !result.mobile) { result.mobile = mobileMatch[0]; usedIdx.add(idx); return; }
    const telMatch = fixed.match(/0(2|[3-6][1-5]?)[-.\s]?\d{3,4}[-.\s]?\d{4}/);
    if (telMatch && !result.telephone) { result.telephone = telMatch[0]; usedIdx.add(idx); return; }
    const emailMatch = line.match(/[\w.+-]+@[\w-]+\.[\w.-]+/);
    if (emailMatch && !result.email) { result.email = emailMatch[0]; usedIdx.add(idx); return; }
    const webMatch = line.match(/(https?:\/\/[\w.-]+|www\.[\w.-]+\.[a-z]{2,})/i);
    if (webMatch && !result.website) { result.website = webMatch[0]; usedIdx.add(idx); return; }
    const posKeyword = POSITION_KEYWORDS.find((k) => line.includes(k));
    if (posKeyword && !result.position) { result.position = line; usedIdx.add(idx); return; }
  });
  lines.forEach((line, idx) => { if (!usedIdx.has(idx)) result.etcCandidates.push(line); });
  return result;
}

// ⚠️ 테스트용 예시 원문(2026-09-04) — 실제 명함 사진 OCR 결과가 대략 이렇게
// 생겼을 거라 가정한 더미 텍스트입니다(일부러 "O1O"처럼 O/0 혼동을 섞어서 위
// 보정 로직이 실제로 작동하는지 시험합니다). 회사명·이름·주소는 일부러 규칙에
// 안 걸리게 둬서, 분류기가 스스로 "모르는 건 손 안 댄다"는 걸 보여줍니다.
const MOCK_OCR_RAW_TEXT = [
  "OO물산", "김철수", "영업팀장", "O1O-1234-5678", "O2-123-4567",
  "sample@example.com", "서울특별시 강남구 테헤란로 123", "신뢰와 정성으로 모시겠습니다",
].join("\n");

// ⚠️ 테스트용 예시 데이터 생성기(2026-09-03~04, 사장님+쳇 확정) — 실제 OCR 엔진은
// 아직 정하지 않았습니다(Tesseract.js/CLOVA OCR/Google Vision 등 후보를 실제
// 명함 사진 몇 장으로 먼저 비교 테스트한 뒤 결정하기로 함). 지금은 위 더미
// 원문(MOCK_OCR_RAW_TEXT)을 extractFieldsFromOcrText()에 그대로 통과시켜서 "원문
// → 분류 → 확인화면"까지 전체 파이프라인을 미리 시험합니다. 실제 엔진을 붙일 때는
// MOCK_OCR_RAW_TEXT 자리에 그 엔진이 준 원문을 넣으면 되고(또는 CLOVA처럼 이미
// 필드로 나눠 주는 엔진이면 이 함수 자체를 건너뛰고 바로 넣으면 됩니다),
// 화면(OcrReviewForm) 쪽은 손댈 필요 없이 그대로 재사용됩니다. 값이 빈
// 문자열이면 "못 읽음/분류 안 됨"이라는 뜻 — 억지로 추측해서 채우지 않습니다.
// 🟡 발견된 한계: 회사명·이름·주소는 지금 규칙(정규식/키워드)만으로는 못 잡아서
// 항상 빈칸입니다 — "기타 후보"에 뒤섞여 들어갈 뿐입니다. 실제 OCR 비교테스트에서
// 이 세 항목을 얼마나 잘 분류하는지가 A안(CLOVA)과 B안(일반OCR+규칙)을 가르는
// 핵심 기준이 될 것 같습니다.
function getMockOcrResult() {
  const extracted = extractFieldsFromOcrText(MOCK_OCR_RAW_TEXT);
  return {
    fields: {
      companyName: "", personName: "", position: extracted.position,
      mobile: extracted.mobile, telephone: extracted.telephone,
      email: extracted.email, website: extracted.website,
      address: "",
    },
    etcCandidates: extracted.etcCandidates,
    rawText: MOCK_OCR_RAW_TEXT,
  };
}

const OCR_REVIEW_FIELDS = [
  { key: "companyName", label: "회사명" }, { key: "personName", label: "이름" },
  { key: "position", label: "직책" }, { key: "mobile", label: "휴대폰" },
  { key: "telephone", label: "회사전화" }, { key: "fax", label: "팩스" }, { key: "email", label: "이메일" },
  { key: "website", label: "홈페이지" }, { key: "address", label: "주소" },
];

// 사진에서 읽어낸 정보를 한 화면에서 전부 검토·수정하고 한 번에 확인하는 폼.
// 사장님 원칙(2026-09-03~04): "OCR이나 AI는 판단자가 아니다 — 읽어서 보여주기만
// 하고, 최종 판단은 전부 고객이 한다." 그래서: ①9개 항목을 전부 똑같이 보여주고
// 신뢰도로 구분하지 않음 ②AI가 읽은 원문을 그대로 볼 수 있게 열어둠(뭘 근거로
// 저렇게 읽었는지 고객이 직접 비교 가능) ③"기타"도 자동으로 하나로 합치지 않고,
// 후보 각각을 체크박스로 보여줘서 고객이 남길 것만 고르게 함.
function OcrReviewForm({ initialValues, etcCandidates = [], rawText, onConfirm, isTest = false }) {
  const [vals, setVals] = useState(() =>
    Object.fromEntries(OCR_REVIEW_FIELDS.map((f) => [f.key, initialValues[f.key] || ""]))
  );
  // ⚠️ 버그수정(2026-09-04, 사장님+아스트라 지적): 미분류 OCR 후보가 기본으로 전부
  // 체크돼 있어서, 고객이 그냥 확인만 눌러도 전부 "기타"에 합쳐져 저장되고
  // 있었습니다. "고객이 명시적으로 고른 내용만 기타에 들어가야 한다"는 원칙에
  // 따라 기본값을 전부 체크 해제로 바꿉니다 — 후보는 보여주되, 실제로 쓰려면
  // 고객이 직접 체크해야 합니다.
  const [checked, setChecked] = useState(() => etcCandidates.map(() => false));
  const [manualEtc, setManualEtc] = useState("");
  const [showRaw, setShowRaw] = useState(false);

  const handleConfirm = () => {
    const etc = [...etcCandidates.filter((_, i) => checked[i]), manualEtc.trim()].filter(Boolean).join(", ");
    onConfirm({ ...vals, etc });
  };

  return (
    <div style={{ marginBottom: 14 }}>
      <div style={{ fontSize: 13, fontWeight: 700, color: "var(--ink)", marginBottom: 4 }}>
        사진에서 읽은 내용을 확인해주세요.
      </div>
      <div style={{ fontSize: 11, color: "var(--ink-soft)", marginBottom: 4 }}>
        인쇄 전에 모든 항목을 직접 확인해 주세요.
      </div>
      {isTest && <div style={{ fontSize: 10.5, color: "var(--stamp)", fontWeight: 700, marginBottom: 8 }}>
        ※ 지금은 테스트 화면입니다. 아래 값은 실제로 사진을 읽은 결과가 아닙니다.
      </div>}
      {rawText && (
        <div style={{ marginBottom: 10 }}>
          <button onClick={() => setShowRaw((v) => !v)} style={{
            background: "none", border: "none", color: "var(--stamp)", fontSize: 11.5, fontWeight: 700,
            cursor: "pointer", fontFamily: "inherit", textDecoration: "underline", padding: 0,
          }}>{showRaw ? "확인한 글자 전체 접기" : "확인한 글자 전체 보기"}</button>
          {showRaw && (
            <pre style={{
              marginTop: 6, background: "var(--paper-deep)", border: "1px solid var(--line)", borderRadius: 8,
              padding: "8px 10px", fontSize: 11, color: "var(--ink-soft)", whiteSpace: "pre-wrap", fontFamily: "inherit",
            }}>{rawText}</pre>
          )}
        </div>
      )}
      {OCR_REVIEW_FIELDS.map((f) => (
        <div key={f.key} style={{ marginBottom: 8 }}>
          <div style={{ fontSize: 10.5, color: "var(--ink-soft)", marginBottom: 3 }}>{f.label}</div>
          <input
            value={vals[f.key] || ""}
            placeholder="직접 입력해주세요"
            onChange={(e) => setVals((v) => ({ ...v, [f.key]: e.target.value }))}
            style={{
              width: "100%", border: "1.5px solid var(--line)", borderRadius: 8, padding: "8px 10px",
              fontSize: 12.5, fontFamily: "inherit", boxSizing: "border-box",
              background: "var(--paper-white)", color: "var(--ink)",
            }}
          />
        </div>
      ))}

      <div style={{ marginBottom: 8 }}>
        <div style={{ fontSize: 10.5, color: "var(--ink-soft)", marginBottom: 3 }}>기타</div>
        {etcCandidates.length > 0 && (
          <div style={{ marginBottom: 6 }}>
            <div style={{ fontSize: 10, color: "var(--ink-soft)", marginBottom: 4 }}>OCR에서 자동으로 찾은 기타 후보 — 필요 없는 건 체크 해제하세요</div>
            {etcCandidates.map((c, i) => (
              <label key={i} style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 12, color: "var(--ink)", marginBottom: 4, cursor: "pointer" }}>
                <input type="checkbox" checked={checked[i]} onChange={() => setChecked((arr) => arr.map((v, idx) => (idx === i ? !v : v)))} />
                {c}
              </label>
            ))}
          </div>
        )}
        <input
          value={manualEtc}
          placeholder="직접 추가 입력"
          onChange={(e) => setManualEtc(e.target.value)}
          style={{
            width: "100%", border: "1.5px solid var(--line)", borderRadius: 8, padding: "8px 10px",
            fontSize: 12.5, fontFamily: "inherit", boxSizing: "border-box",
            background: "var(--paper-white)", color: "var(--ink)",
          }}
        />
      </div>

      <div style={{ fontSize: 10.5, color: "var(--ink-soft)", textAlign: "center", marginBottom: 6 }}>
        입력된 내용이 실제 명함에 그대로 인쇄됩니다.
      </div>
      <button onClick={handleConfirm} style={{
        width: "100%", background: "var(--stamp)", border: "none", color: "#fff", borderRadius: 10,
        padding: "11px 0", fontSize: 13, fontWeight: 700, cursor: "pointer", fontFamily: "inherit",
      }}>모든 내용을 확인했습니다</button>
    </div>
  );
}

// ==================== 명함 글자 판독 → 고객 확인 (2026-11-22) ====================
// 서버(/api/ocr-read, gpt-5.4-mini)가 펴진 명함 사진의 글자를 읽고, 고객이 줄마다 원본 확대
// 사진을 보며 확정합니다. 사장님·쳇과 정한 원칙:
//  - AI 판독은 "제안값"일 뿐 — 모든 줄을 고객이 확인해야 다음으로 넘어감
//  - 확인 필요 줄(AI 불확실·한자·맞춤법 제안·두 번 읽은 결과가 다름)은 맨 위, 명함 전체는 화면 위에 고정(눌러서 크게)
//  - 이름·회사명·전화·이메일·홈페이지·주소는 표시가 없어도 한 줄씩 확인 (한꺼번에 확인 불가)
//    (2026-11-21 시험에서 이름 오류 '송종근', '오영복'이 표시 없이 지나간 일 때문)
//  - 맞춤법 제안은 자동 반영하지 않음 — 고객이 [제안대로 바꾸기]를 눌러야만 바뀜
//  - 확인한 값은 잠금: 이후 AI가 다시 읽어도 바꾸지 않음(확인 시작 후에는 다시 읽기 자체를 막음)
//  - AI 좌표로 줄마다 잘라 보이지 않음(엉뚱한 곳을 보여 줄 수 있어서) — 전체 명함을 보며 비교

const OCR_MUST_CHECK_TYPES = ["name", "company", "phone", "mobile", "fax", "email", "website", "address"];
const OCR_TYPE_KO = {
  company: "회사·단체", name: "이름", title: "직함", department: "부서", phone: "전화", mobile: "휴대폰",
  fax: "팩스", email: "이메일", website: "홈페이지", address: "주소", career: "경력", slogan: "문구",
  logo_text: "로고 글자", form: "양식", label: "항목", other: "기타", unreadable: "도장·낙관",
};

// 펴진 명함(data URL)을 서버로 보내 판독
async function requestCardOcr(flatDataUrl) {
  const res = await fetch(`${RENDER_API_BASE}/api/ocr-read`, {
    method: "POST", headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ image: flatDataUrl }),
  });
  let data = null;
  try { data = await res.json(); } catch { /* 서버가 JSON이 아닌 응답(예: 잠든 서버 깨우는 중) */ }
  if (!res.ok) throw new Error((data && data.error) || `판독 서버 응답 오류 (${res.status})`);
  return data;
}

// 서버 결과 → 화면용 줄 목록 (위치 확인·정렬 포함)
function prepareOcrLines(serverLines) {
  const lines = serverLines.map((l, i) => {
    const why = [];
    if (l.type === "unreadable") why.push("도장·낙관 등 글자를 읽지 않은 부분");
    else {
      if (l.hasHanja) why.push("한자가 있어요");
      else if (l.hanjaCardCheck) why.push("원래 한자였는지 확인해 주세요");
      const srDiff = l.secondRead && (l.secondRead.status === "diff" || l.secondRead.status === "missing");
      if (l.unsure && !l.hasHanja && !l.hanjaCardCheck && !srDiff) why.push("AI가 확실하지 않대요" + (l.unsureChars ? ` (${l.unsureChars})` : ""));
      if (l.suggestion) why.push("맞춤법이 달라 보여요(원본 그대로가 원칙)");
      // 서버가 같은 사진을 두 번 읽어 비교한 결과 (2026-11-22)
      if (l.secondRead && l.secondRead.status === "diff") why.push("두 번 읽은 결과가 달라요");
      if (l.secondRead && l.secondRead.status === "missing") why.push("다시 읽었을 때는 없던 줄이에요(명함에 정말 있는지)");
    }
    return {
      id: i, aiText: l.text || "", text: l.text || "", type: l.type, suggestion: l.suggestion || "",
      altText: l.secondRead && l.secondRead.status === "diff" ? l.secondRead.alt || "" : "",
      flagged: why.length > 0, why,
      mustCheck: OCR_MUST_CHECK_TYPES.includes(l.type),
      status: "pending", // pending → confirmed(그대로) / edited(고침) / removed(뺌)
    };
  });
  const rank = (l) => (l.flagged ? 0 : l.mustCheck ? 1 : 2);
  return lines.sort((a, b) => rank(a) - rank(b) || a.id - b.id);
}

function OcrCardViewer({ flatUrl }) {
  const [zoom, setZoom] = useState(false);
  return (
    <div style={{ position: "sticky", top: 62, zIndex: 3, background: "var(--paper, #faf8f4)", paddingBottom: 6, marginBottom: 6 }}>  {/* 62 = 위쪽 제목줄(TopBar) 높이 */}
      <div style={{ overflow: "auto", maxHeight: zoom ? 230 : "none", borderRadius: 8, border: "1px solid var(--line)" }}>
        <img src={flatUrl} alt="찍은 명함" onClick={() => setZoom((z) => !z)}
          style={{ width: zoom ? "260%" : "100%", maxWidth: "none", display: "block", cursor: zoom ? "zoom-out" : "zoom-in" }} />
      </div>
      <div style={{ fontSize: 10.5, color: "var(--ink-soft)", marginTop: 3 }}>
        {zoom ? "손가락으로 밀어 보세요. 다시 누르면 작게 봐요." : "명함을 누르면 크게 볼 수 있어요."}
      </div>
    </div>
  );
}

function OcrLineConfirm({ flatUrl, state, setState, onDone, onManual }) {
  // state: { status: "idle"|"reading"|"error"|"ready", lines, error, meta }
  // 요청마다 표시(token)를 남겨, 화면을 떠났거나 새 요청이 시작된 뒤 도착한 응답은 버림.
  // (상태가 idle→reading으로 바뀌는 것 자체로 요청이 취소되지 않게 — 2026-11-22 시험에서 발견한 버그)
  const reqRef = useRef(null);
  useEffect(() => () => { reqRef.current = null; }, []);
  useEffect(() => {
    if (!flatUrl || state.status !== "idle") return;
    const token = {}; reqRef.current = token;
    setState((s) => ({ ...s, status: "reading", error: "" }));
    (async () => {
      try {
        const r = await requestCardOcr(flatUrl);
        const lines = prepareOcrLines(r.lines || []);
        if (reqRef.current === token) setState({ status: "ready", lines, error: "", meta: { model: r.model, hanjaCard: !!r.hanjaCard, at: new Date().toISOString() } });
      } catch (e) {
        if (reqRef.current === token) setState((s) => ({ ...s, status: "error", error: e.message || "판독에 실패했어요" }));
      }
    })();
  }, [flatUrl, state.status]);

  const btn = (bg, color = "#fff", border = "none") => ({ background: bg, color, border, borderRadius: 8, padding: "7px 10px", fontSize: 12, fontWeight: 700, cursor: "pointer", fontFamily: "inherit" });

  if (!flatUrl) return <ChatChoiceRow options={[{ label: "직접 입력할게요", value: "m" }]} onPick={onManual} />;
  if (state.status === "idle" || state.status === "reading") {
    return <div style={{ fontSize: 12.5, color: "var(--ink-soft)", padding: "10px 0" }}>명함 글자를 읽고 있어요… (5~10초, 서버가 쉬고 있었다면 30초쯤 걸릴 수 있어요)</div>;
  }
  if (state.status === "error") {
    return (
      <div style={{ marginBottom: 14 }}>
        <div style={{ fontSize: 12.5, color: "var(--stamp)", marginBottom: 8 }}>글자를 읽지 못했어요: {state.error}</div>
        <div style={{ display: "flex", gap: 6 }}>
          <button style={btn("var(--stamp)")} onClick={() => setState({ status: "idle", lines: [], error: "" })}>다시 읽기</button>
          <button style={btn("var(--paper-white)", "var(--ink)", "1.5px solid var(--line)")} onClick={onManual}>직접 입력할게요</button>
        </div>
      </div>
    );
  }

  const lines = state.lines;
  const upd = (id, patch) => setState((s) => ({ ...s, lines: s.lines.map((l) => (l.id === id && !l.locked ? { ...l, ...patch } : l)) }));
  const lock = (id, status) => setState((s) => ({ ...s, lines: s.lines.map((l) => (l.id === id ? { ...l, status, locked: true, confirmedAt: new Date().toISOString() } : l)) }));
  const unlock = (id) => setState((s) => ({ ...s, lines: s.lines.map((l) => (l.id === id ? { ...l, status: "pending", locked: false } : l)) }));
  const pending = lines.filter((l) => l.status === "pending");
  const batchable = pending.filter((l) => !l.flagged && !l.mustCheck && l.type !== "unreadable");
  const done = lines.length - pending.length;

  return (
    <div style={{ marginBottom: 14 }}>
      <OcrCardViewer flatUrl={flatUrl} />
      <div style={{ fontSize: 13, fontWeight: 700, color: "var(--ink)", marginBottom: 2 }}>명함에 인쇄된 글자가 맞나요?</div>
      <div style={{ fontSize: 11, color: "var(--ink-soft)", marginBottom: 8 }}>
        위 명함과 한 줄씩 비교해 주세요. 확인한 글자는 그대로 인쇄되고, 이후 AI가 바꾸지 않아요. ({done}/{lines.length}줄 확인)
      </div>
      {lines.map((l) => {
        const isDone = l.status !== "pending";
        const border = l.flagged && !isDone ? "2px solid var(--stamp)" : "1px solid var(--line)";
        return (
          <div key={l.id} data-ocr-line={l.id} style={{ border, borderRadius: 10, padding: 8, marginBottom: 8, background: isDone ? "var(--paper-deep)" : "var(--paper-white)", opacity: l.status === "removed" ? 0.55 : 1 }}>
            <div style={{ fontSize: 10.5, color: "var(--ink-soft)", marginBottom: 4 }}>
              {OCR_TYPE_KO[l.type] || l.type}
              {l.flagged && !isDone && <span style={{ color: "var(--stamp)", fontWeight: 700 }}> · 확인 필요: {l.why.join(", ")}</span>}
            </div>
            {l.type === "unreadable" && !l.text ? (
              <div style={{ fontSize: 12, color: "var(--ink)" }}>
                {isDone ? (l.status === "removed" ? "그림(도장·낙관)으로 두기로 했어요." : `글자로 넣기: ${l.text}`) : "명함의 도장·낙관은 글자로 옮기지 않고 그림으로 둬요. 글자라면 직접 입력해 주세요."}
                {!isDone && (
                  <div style={{ display: "flex", gap: 6, marginTop: 6 }}>
                    <button style={btn("var(--stamp)")} onClick={() => lock(l.id, "removed")}>그림으로 둘게요</button>
                    <input placeholder="글자라면 입력" onChange={(e) => upd(l.id, { draft: e.target.value })} style={{ flex: 1, minWidth: 0, border: "1.5px solid var(--line)", borderRadius: 8, padding: "6px 8px", fontSize: 12.5, fontFamily: "inherit" }} />
                    <button style={btn("var(--ink)")} onClick={() => { if ((l.draft || "").trim()) { upd(l.id, { text: l.draft.trim(), type: "other" }); lock(l.id, "edited"); } }}>넣기</button>
                  </div>
                )}
              </div>
            ) : (
              <>
                <input value={l.text} disabled={isDone} onChange={(e) => upd(l.id, { text: e.target.value })}
                  style={{ width: "100%", marginTop: 0, border: "1.5px solid var(--line)", borderRadius: 8, padding: "8px 10px", fontSize: 14, fontFamily: "inherit", boxSizing: "border-box", background: isDone ? "transparent" : "var(--paper-white)", color: "var(--ink)", textDecoration: l.status === "removed" ? "line-through" : "none" }} />
                {l.altText && !isDone && l.text !== l.altText && (
                  <div style={{ fontSize: 11.5, color: "var(--ink)", marginTop: 4, background: "var(--paper-deep)", borderRadius: 6, padding: "5px 8px" }}>
                    다시 읽었을 때: <b>{l.altText}</b>{" "}
                    <button style={{ ...btn("none", "var(--stamp)"), padding: 0, textDecoration: "underline" }} onClick={() => upd(l.id, { text: l.altText })}>이걸로 바꾸기</button>
                    <div style={{ fontSize: 10.5, color: "var(--ink-soft)" }}>위 명함을 보고 맞는 쪽을 고르거나 직접 고쳐 주세요.</div>
                  </div>
                )}
                {l.suggestion && !isDone && (
                  <div style={{ fontSize: 11, color: "var(--ink-soft)", marginTop: 4 }}>
                    맞춤법 제안: <b>{l.suggestion}</b> — 명함에 인쇄된 그대로가 원칙이에요. 일부러 바꾸고 싶을 때만{" "}
                    <button style={{ ...btn("none", "var(--stamp)"), padding: 0, textDecoration: "underline" }} onClick={() => upd(l.id, { text: l.suggestion })}>제안대로 바꾸기</button>
                  </div>
                )}
                <div style={{ display: "flex", gap: 6, marginTop: 6, alignItems: "center" }}>
                  {!isDone ? (
                    <>
                      <button style={btn("var(--stamp)")} onClick={() => lock(l.id, l.text.trim() === l.aiText.trim() ? "confirmed" : "edited")}>
                        {l.text.trim() === l.aiText.trim() ? "맞아요" : "고친 대로 확인"}
                      </button>
                      <button style={btn("var(--paper-white)", "var(--ink-soft)", "1.5px solid var(--line)")} onClick={() => lock(l.id, "removed")}>이 줄 빼기</button>
                    </>
                  ) : (
                    <>
                      <span style={{ fontSize: 11.5, color: "var(--ink-soft)" }}>{l.status === "removed" ? "뺐어요" : l.status === "edited" ? "고쳐서 확인했어요" : "확인했어요"}</span>
                      <button style={{ ...btn("none", "var(--ink-soft)"), padding: 0, textDecoration: "underline", fontWeight: 400 }} onClick={() => unlock(l.id)}>다시 고치기</button>
                    </>
                  )}
                </div>
              </>
            )}
          </div>
        );
      })}
      <button onClick={() => { setState((s) => ({ ...s, manualLines: [...(s.manualLines || []), ""] })); }}
        style={{ ...btn("none", "var(--stamp)"), padding: "4px 0", textDecoration: "underline" }}>+ 빠진 줄 직접 추가</button>
      {(state.manualLines || []).map((t, i) => (
        <input key={i} value={t} placeholder="명함에 있는데 빠진 글자" onChange={(e) => setState((s) => ({ ...s, manualLines: s.manualLines.map((v, k) => (k === i ? e.target.value : v)) }))}
          style={{ width: "100%", marginTop: 6, border: "1.5px solid var(--line)", borderRadius: 8, padding: "8px 10px", fontSize: 13, fontFamily: "inherit", boxSizing: "border-box" }} />
      ))}
      <div style={{ marginTop: 10, display: "flex", flexDirection: "column", gap: 6 }}>
        {batchable.length > 0 && (
          <button style={btn("var(--paper-white)", "var(--ink)", "1.5px solid var(--line)")}
            onClick={() => setState((s) => ({ ...s, lines: s.lines.map((l) => (batchable.some((b) => b.id === l.id) ? { ...l, status: "confirmed", locked: true, confirmedAt: new Date().toISOString() } : l)) }))}>
            표시 없는 나머지 {batchable.length}줄(경력·문구 등)도 맞아요
          </button>
        )}
        <button disabled={pending.length > 0} onClick={() => onDone(lines, (state.manualLines || []).map((t) => t.trim()).filter(Boolean))}
          style={{ ...btn(pending.length ? "var(--line)" : "var(--stamp)"), padding: "11px 0", fontSize: 13, cursor: pending.length ? "default" : "pointer" }}>
          {pending.length ? `아직 확인 안 한 줄이 ${pending.length}개 있어요` : "모든 글자를 확인했어요"}
        </button>
      </div>
    </div>
  );
}

// 확인한 줄 → 기존 정보 항목(회사명·이름·…)으로 나누기. 확인 화면(OcrReviewForm)에서 고객이 다시 볼 수 있음.
function ocrLinesToFields(lines, manualLines = []) {
  const ok = lines.filter((l) => l.status === "confirmed" || l.status === "edited").map((l) => ({ ...l, text: l.text.trim() })).filter((l) => l.text);
  const take = (type) => ok.filter((l) => l.type === type).map((l) => l.text);
  const squeezeName = (s) => (/^[一-鿿가-힣](\s+[一-鿿가-힣]){1,4}$/.test(s) ? s.replace(/\s+/g, "") : s);
  const num = (s) => { const m = s.match(/0\d{1,3}[)\-.\s]*\d{3,4}[-.\s]*\d{4}(\s*~\s*\d+)?/); return m ? m[0].trim() : s.replace(/^[A-Za-z.\s:]+/, "").trim(); };
  const email = (s) => { const m = s.match(/[\w.+-]+@[\w-]+(\.[\w-]+)+/); return m ? m[0] : s; };
  const web = (s) => { const m = s.match(/(https?:\/\/\S+|www\.\S+|[\w-]+(\.[\w-]+)+\.[a-z]{2,}\S*)/i); return m ? m[0] : s; };
  const used = new Set();
  const first = (type, f = (x) => x) => { const l = ok.find((x) => x.type === type && !used.has(x)); if (!l) return ""; used.add(l); return f(l.text); };
  // 직함이 "대 표"처럼 띄어 쓰여 '항목'·'기타'로 분류된 경우도 직함으로 (흔한 직함 낱말만)
  const POS = ["대표", "대표이사", "회장", "부회장", "사장", "부사장", "전무", "상무", "이사", "본부장", "실장", "부장", "차장", "과장", "팀장", "대리", "주임", "사원", "원장", "소장", "총재", "지회장", "지부장"];
  const posLine = () => { const l = ok.find((x) => !used.has(x) && ["title", "label", "other"].includes(x.type) && POS.includes(x.text.replace(/\s+/g, ""))); if (!l) return ""; used.add(l); return l.text.replace(/\s+/g, ""); };
  // 이름 줄에 직함이 붙어 읽힌 경우("金 昌 元 대표이사") → 이름과 직함으로 나눔
  let nameText = first("name"), nameTitle = "";
  const tail = POS.slice().sort((a, b) => b.length - a.length).find((k) => nameText.replace(/\s+/g, "").endsWith(k) && nameText.replace(/\s+/g, "").length > k.length);
  if (tail) { const i = nameText.lastIndexOf(tail[0]); if (i > 0 && nameText.slice(i).replace(/\s+/g, "") === tail) { nameTitle = tail; nameText = nameText.slice(0, i).trim(); } }
  const fields = {
    companyName: first("company", squeezeName), personName: squeezeName(nameText), position: first("title") || posLine() || nameTitle,
    mobile: first("mobile", num), telephone: first("phone", num), fax: first("fax", num),
    email: first("email", email), website: first("website", web),
    // 주소는 첫 주소 줄 + 명함에서 바로 이어지는 주소 줄만 합침
    // (해외법인 주소처럼 다른 줄 뒤에 따로 있는 주소는 기타로 — GIP 명함 시험)
    address: (() => {
      const adr = ok.filter((l) => l.type === "address").sort((a, b) => a.id - b.id);
      if (!adr.length) return "";
      const out = [adr[0]];
      for (const l of adr.slice(1)) { if (l.id === out[out.length - 1].id + 1) out.push(l); else break; }
      out.forEach((l) => used.add(l));
      return out.map((l) => l.text).join(" ");
    })(),
  };
  const etcCandidates = [...ok.filter((l) => !used.has(l)).map((l) => l.text), ...manualLines];
  return { fields, etcCandidates, rawText: ok.map((l) => l.text).concat(manualLines).join("\n") };
}

// ⚠️ 2026-09-22 추가(사장님 지적: "실제 정보 입력 → 모형 선택 → 위치 조절 →
// 최종 출력까지 연결해서 검증해야 한다" — logoAspectRatio 스코프 버그를 개별
// 함수 시험만으로는 못 잡았던 것과 같은 이유) — testSeed는 실제 서비스
// 경로에서는 절대 안 쓰이는(항상 null) 테스트 전용 진입점입니다. 채팅 흐름을
// 처음부터 클릭으로 재현하지 않고도, 실제로 마운트된 AiConsultDesign
// 컴포넌트 트리 안에서 templateChoice 등 특정 화면을 직접 검증할 수 있게
// 해서, "함수는 맞는데 화면 연결이 끊겨 있다"는 종류의 버그를 잡습니다.
// ==================== domain/consult/editCommands ====================
// 2026-10-01 신규(대표님 확정 — "대화형 편집, API 없이 뼈대부터") —
// 고객이 편집 화면에서 입력한 문장을 "엔진 명령"으로 바꾸는 층입니다.
//
// 구조(4중 방어막 원칙 그대로):
//   고객 문장 → ① 해석(지금은 규칙 해석기, 나중에 AI로 교체) → 명령 목록
//            → ② 명령 검증(허용된 명령·대상·범위인지) → ③ 고객에게 "이렇게 바꿀까요?" 확인
//            → ④ 고객 승인 시 디자인엔진이 적용 → ⑤ 겹침·안전영역 검사 결과를 그대로 보고
// 해석기는 명령을 "제안"만 하고, 시스템 상태를 직접 바꾸지 않습니다.
// 엔진은 고객이 승인한 명령만 실행하고, 결과에 문제가 있어도 스스로 고치지 않습니다(TEXT-EDIT-001).
//
// 명령 종류(이 목록 밖의 명령은 검증 단계에서 전부 거절):
//   move        { target, dxMm, dyMm }            위치 이동(누적 이동량)
//   resize      { target, deltaPt | toPt | factor } 글자 크기(pt) / 로고는 배율(factor)
//   spacing     { target, deltaMm }               자간
//   font        { target, fontId }                글씨체(4종)
//   place       { target, ref, where }            "직위를 이름 위로" — ref 기준 위/아래/왼쪽/오른쪽
//   setText     { target, value }                 내용 수정(전화번호·이메일 등)
//   background  { color }                         배경 단색(HEX는 그대로 보존 — COLOR-001)
//   reset       { target | "all" }                원래대로
//   undo        {}                                방금 적용한 것 되돌리기(확인 없이 바로)

const EDIT_TARGET_WORDS = [
  // 순서 중요: 더 구체적인 말을 먼저 찾습니다(예: "회사명"을 "회사"보다 먼저, "휴대폰"을 "전화"보다 먼저).
  ["company", /회사\s*명|회사\s*이름|상호/],
  ["personName", /이름|성함|성명/],
  ["position", /직위|직함|직책|직급|직무/],
  ["logo", /로고/],
  ["mobile", /휴대\s*폰|핸드\s*폰|휴대\s*전화|모바일|폰\s*번호|(?:^|\s)M\.?(?=\s|$)/i],
  ["telephoneFax", /사무실\s*전화|회사\s*전화|일반\s*전화|유선|팩스|전화|(?:^|\s)T\.?(?=\s|$)/i],
  ["address", /주소/],
  ["email", /이메일|메일|e-?mail/i],
  ["website", /홈페이지|웹\s*사이트|사이트|웹|url/i],
  ["introText", /소개\s*문구|소개|경력/],
  ["etc", /기타/],
];
const EDIT_FONT_WORDS = [
  ["suit", /둥근\s*고딕|둥근|suit/i],
  ["regularGothic", /고딕|프리텐다드|pretendard|기본\s*글씨/i],
  ["myeongjo", /명조|세리프|serif/i],
  ["handwriting", /손\s*글씨|필기|손글/],
];
const EDIT_COLOR_WORDS = [
  ["#FFFFFF", /흰|하얀|화이트/], ["#1A1A22", /검정|검은|블랙/], ["#1F3A5F", /남색|네이비/],
  ["#0E7C6E", /청록/], ["#7CC4F0", /하늘/], ["#2563EB", /파랑|파란|블루/], ["#C0392B", /빨강|빨간|레드/],
  ["#2E7D53", /초록|녹색|그린/], ["#9CA3AF", /회색|그레이/], ["#EFE6D8", /베이지|아이보리/],
  ["#F2C94C", /노랑|노란|옐로/], ["#6C4CF0", /보라|퍼플/], ["#F4A6C0", /분홍|핑크/], ["#B8860B", /금색|골드/],
];
const EDIT_RANGES = { minPt: 5, maxPt: 30, maxMoveMm: 25, maxSpacingMm: 2, minLogoFactor: 0.3, maxLogoFactor: 2.5 };

function findEditTargets(text, fieldValues = null) {
  const found = [];
  let rest = ` ${text} `;
  // 고객이 입력한 실제 내용으로 부르는 경우("대표를 이름 위로", "홍길동을 크게") — 내용이 2글자 이상일 때만
  if (fieldValues) {
    for (const [kind, value] of Object.entries(fieldValues)) {
      const v = String(value || "").trim();
      if (v.length < 2) continue;
      const i = rest.indexOf(v);
      if (i >= 0) { found.push({ kind, index: i }); rest = rest.slice(0, i) + " ".repeat(v.length) + rest.slice(i + v.length); }
    }
  }
  for (const [kind, re] of EDIT_TARGET_WORDS) {
    const m = rest.match(re);
    if (m) {
      found.push({ kind, index: m.index });
      rest = rest.slice(0, m.index) + " ".repeat(m[0].length) + rest.slice(m.index + m[0].length);
    }
  }
  return found.sort((a, b) => a.index - b.index).map((f) => f.kind);
}

function amountFrom(text, kind) {
  const mm = text.match(/(\d+(?:\.\d+)?)\s*(mm|밀리|미리)/i);
  if (kind === "move") {
    if (mm) return Number(mm[1]);
    if (/조금|살짝|약간|미세/.test(text)) return 0.5;
    if (/많이|크게|한참|훨씬/.test(text)) return 3;
    return 1;
  }
  if (kind === "spacing") {
    if (mm) return Number(mm[1]);
    if (/조금|살짝|약간/.test(text)) return 0.05;
    if (/많이|훨씬/.test(text)) return 0.3;
    return 0.1;
  }
  if (kind === "size") {
    const pt = text.match(/(\d+(?:\.\d+)?)\s*(pt|포인트|p)(?![a-z])/i);
    if (pt) return { toPt: Number(pt[1]) };
    if (/조금|살짝|약간/.test(text)) return { delta: 0.5 };
    if (/많이|훨씬|확/.test(text)) return { delta: 2 };
    return { delta: 1 };
  }
  return null;
}

// 한 덩어리(절)를 명령으로. ctx: { selectedKind }
function parseEditClause(clause, ctx = {}) {
  const t = clause.trim();
  if (!t) return { commands: [] };
  if (/^(되돌려|되돌리기|취소|방금\s*(거|것)\s*취소|실행\s*취소|undo)/i.test(t) || /되돌려\s*줘|되돌려$/.test(t)) return { commands: [{ type: "undo" }] };

  const targets = [...new Set(findEditTargets(t, ctx.fieldValues))];
  const wantsBackground = /배경/.test(t);
  const hex = t.match(/#[0-9a-fA-F]{6}\b/);

  // 배경색
  if (wantsBackground) {
    const named = EDIT_COLOR_WORDS.find(([, re]) => re.test(t));
    const color = hex ? hex[0].toUpperCase() : named ? named[0] : null;
    if (!color) return { commands: [], clarify: "배경을 어떤 색으로 할까요? 색 이름(예: 남색, 베이지)이나 #1F3A5F 같은 색 코드로 말씀해주세요." };
    return { commands: [{ type: "background", color }] };
  }

  // 원래대로
  if (/원래\s*대로|처음\s*대로|초기화|기본\s*값|리셋/.test(t)) {
    if (/전체|전부|모두|다\b/.test(t) || !targets.length) return { commands: [{ type: "reset", target: targets.length ? targets[0] : (ctx.selectedKind || "all") }] };
    return { commands: targets.map((k) => ({ type: "reset", target: k })) };
  }

  // 내용 수정: "휴대폰 번호를 010-9999-8888로 바꿔줘", "이메일을 a@b.com으로 변경"
  const setM = t.match(/(?:을|를|은|는)?\s*([^\s].*?)\s*(?:으로|로)\s*(바꿔|바꾸|변경|수정|고쳐)/);
  if (setM && targets.length === 1 && !/(위|아래|밑|왼쪽|오른쪽|옆|좌측|우측)\s*(으로|로)?\s*(바꿔|바꾸|변경|수정|고쳐)/.test(t)
      && !EDIT_FONT_WORDS.some(([, re]) => re.test(setM[1])) && !/글씨|서체|폰트|크기|색/.test(setM[1])) {
    // 대상 낱말 뒤의 값만 남김
    let value = setM[1];
    const tw = EDIT_TARGET_WORDS.find(([k]) => k === targets[0])[1];
    const after = value.replace(new RegExp(`^.*?(${tw.source})(\\s*번호|\\s*주소)?\\s*(을|를|은|는)?\\s*`, tw.flags), "");
    value = after.trim().replace(/^['"“”‘’]|['"“”‘’]$/g, "");
    if (value) return { commands: [{ type: "setText", target: targets[0], value }] };
  }

  // 상대 배치: "직위를 이름 위로", "대표를 이름 옆에"
  const rel = t.match(/(위|아래|밑|왼쪽|오른쪽|옆|좌측|우측)\s*(으로|로|에|쪽)/);
  if (rel && targets.length >= 2) {
    const where = { 위: "above", 아래: "below", 밑: "below", 왼쪽: "left", 좌측: "left", 오른쪽: "right", 우측: "right", 옆: "right" }[rel[1]];
    return { commands: [{ type: "place", target: targets[0], ref: targets[1], where }] };
  }

  const subjects = targets.length ? targets : ctx.selectedKind ? [ctx.selectedKind] : [];
  const cmds = [];
  let clarify = null;

  // 글씨체
  if (/글씨\s*체|서체|폰트|글꼴/.test(t) || EDIT_FONT_WORDS.some(([, re]) => re.test(t))) {
    const f = EDIT_FONT_WORDS.find(([, re]) => re.test(t));
    if (!f) clarify = "어떤 글씨체로 바꿀까요? 고딕·둥근고딕·명조·손글씨 중에서 골라주세요.";
    else subjects.forEach((k) => cmds.push({ type: "font", target: k, fontId: f[0] }));
  }
  // 자간
  if (/자간|글자\s*사이|글자\s*간격|띄어|붙여/.test(t)) {
    const sign = /좁|줄|붙|촘촘/.test(t) ? -1 : 1;
    const a = amountFrom(t, "spacing");
    subjects.forEach((k) => cmds.push({ type: "spacing", target: k, deltaMm: sign * a }));
  } else {
    // 크기
    const up = /크게|키워|키우|확대|크기.*(늘|키)|더\s*크|굵고\s*크/.test(t);
    const down = /작게|줄여|줄이|축소|작아|크기.*줄/.test(t);
    const toPt = /(\d+(?:\.\d+)?)\s*(pt|포인트)(?![a-z])/i.test(t);
    const isMove = /(위|아래|밑|왼쪽|오른쪽|좌측|우측)\s*(으로|로|쪽)|올려|내려|올리|내리/.test(t);
    if ((up || down || toPt) && !isMove) {
      const a = amountFrom(t, "size");
      subjects.forEach((k) => {
        if (k === "logo") cmds.push({ type: "resize", target: k, factor: up ? (a.delta >= 2 ? 1.25 : a.delta <= 0.5 ? 1.05 : 1.1) : (a.delta >= 2 ? 0.8 : a.delta <= 0.5 ? 0.95 : 0.9) });
        else if (a.toPt) cmds.push({ type: "resize", target: k, toPt: a.toPt });
        else cmds.push({ type: "resize", target: k, deltaPt: up ? a.delta : -a.delta });
      });
    }
    // 이동
    if (isMove) {
      const a = amountFrom(t, "move");
      let dx = 0, dy = 0;
      if (/위\s*(으로|로|쪽)|올려|올리/.test(t)) dy -= a;
      if (/(아래|밑)\s*(으로|로|쪽)|내려|내리/.test(t)) dy += a;
      if (/(왼쪽|좌측)/.test(t)) dx -= a;
      if (/(오른쪽|우측)/.test(t)) dx += a;
      subjects.forEach((k) => cmds.push({ type: "move", target: k, dxMm: dx, dyMm: dy }));
    }
  }
  if (!cmds.length && !clarify && !subjects.length && /크게|작게|위로|아래로|왼쪽|오른쪽|올려|내려|글씨|자간/.test(t)) {
    clarify = "어느 항목을 바꿀까요? 명함에서 항목을 눌러 선택하시거나 '이름', '주소'처럼 말씀해주세요.";
  }
  return { commands: cmds, clarify };
}

// 문장 전체 → 여러 절로 나눠 해석
function parseEditRequest(text, ctx = {}) {
  const clauses = String(text || "")
    .split(/\n|,|，|그리고|하고\s|이랑\s(?=.*(크게|작게|위로|아래로))|\.\s|또\s/)
    .map((s) => (s || "").trim()).filter(Boolean)
    .filter((s) => !/^(크게|작게|위로|아래로)$/.test(s) || true);
  const commands = [];
  const clarifies = [];
  let carry = null; // "이름이랑 직위 크게" 처럼 대상만 있는 절은 다음 절과 합침
  for (const c0 of clauses) {
    const c = carry ? `${carry} ${c0}` : c0;
    const r = parseEditClause(c, ctx);
    if (!r.commands.length && !r.clarify && findEditTargets(c, ctx.fieldValues).length && !/(크게|작게|위로|아래로|바꿔|글씨|자간|원래)/.test(c)) { carry = c; continue; }
    carry = null;
    commands.push(...r.commands);
    if (r.clarify) clarifies.push(r.clarify);
  }
  return { commands, clarify: clarifies[0] || null, understood: commands.length > 0 };
}

// ② 명령 검증 — ctx: { availableKinds:Set, currentPt(kind), currentSpacing(kind), currentLogoFactor? }
function validateEditCommands(commands, ctx) {
  const ok = [], rejected = [];
  const has = (k) => ctx.availableKinds?.has(k);
  const label = (k) => (ctx.labelOf ? ctx.labelOf(k) : k);
  for (const c of commands) {
    switch (c.type) {
      case "undo": ok.push(c); break;
      case "background":
        if (/^#[0-9A-F]{6}$/i.test(c.color)) ok.push(c); else rejected.push({ c, why: "색 코드를 알아보지 못했어요." });
        break;
      case "reset":
        if (c.target === "all" || has(c.target)) ok.push(c); else rejected.push({ c, why: `${label(c.target)}은(는) 이 디자인에 없어요.` });
        break;
      case "move":
        if (!has(c.target)) { rejected.push({ c, why: `${label(c.target)}은(는) 이 디자인에 없어요.` }); break; }
        if (Math.abs(c.dxMm) > EDIT_RANGES.maxMoveMm || Math.abs(c.dyMm) > EDIT_RANGES.maxMoveMm) { rejected.push({ c, why: `한 번에 ${EDIT_RANGES.maxMoveMm}mm까지만 옮길 수 있어요.` }); break; }
        ok.push(c); break;
      case "resize": {
        if (!has(c.target)) { rejected.push({ c, why: `${label(c.target)}은(는) 이 디자인에 없어요.` }); break; }
        if (c.target === "logo") {
          if (!(c.factor >= EDIT_RANGES.minLogoFactor && c.factor <= EDIT_RANGES.maxLogoFactor)) { rejected.push({ c, why: "로고 크기 배율이 범위를 벗어났어요." }); break; }
          ok.push(c); break;
        }
        const cur = ctx.currentPt?.(c.target);
        const next = c.toPt != null ? c.toPt : (cur != null ? Math.round(cur * 10) / 10 + c.deltaPt : null);
        if (next == null) { rejected.push({ c, why: `${label(c.target)}의 현재 크기를 알 수 없어요.` }); break; }
        if (next < EDIT_RANGES.minPt || next > EDIT_RANGES.maxPt) { rejected.push({ c, why: `글자 크기는 ${EDIT_RANGES.minPt}~${EDIT_RANGES.maxPt}pt 사이로만 바꿀 수 있어요.` }); break; }
        ok.push({ ...c, fromPt: cur != null ? Math.round(cur * 10) / 10 : null, toPt: Math.round(next * 10) / 10 }); break;
      }
      case "spacing": {
        if (!has(c.target) || c.target === "logo") { rejected.push({ c, why: `${label(c.target)}은(는) 자간을 바꿀 수 없어요.` }); break; }
        const cur = ctx.currentSpacing?.(c.target) ?? 0;
        const next = Math.round((cur + c.deltaMm) * 1000) / 1000;
        if (Math.abs(next) > EDIT_RANGES.maxSpacingMm) { rejected.push({ c, why: "자간이 범위를 벗어났어요." }); break; }
        ok.push({ ...c, fromMm: cur, toMm: next }); break;
      }
      case "font":
        if (!has(c.target) || c.target === "logo") { rejected.push({ c, why: `${label(c.target)}은(는) 글씨체를 바꿀 수 없어요.` }); break; }
        if (!["regularGothic", "suit", "myeongjo", "handwriting"].includes(c.fontId)) { rejected.push({ c, why: "그 글씨체는 아직 없어요." }); break; }
        ok.push(c); break;
      case "place":
        if (!has(c.target) || !has(c.ref) || c.target === c.ref) { rejected.push({ c, why: "옮길 항목이나 기준 항목을 찾지 못했어요." }); break; }
        ok.push(c); break;
      case "setText":
        if (!ctx.editableTextKinds?.has(c.target)) { rejected.push({ c, why: `${label(c.target)} 내용은 여기서 바꿀 수 없어요.` }); break; }
        if (!c.value || c.value.length > 80) { rejected.push({ c, why: "바꿀 내용이 비어 있거나 너무 길어요." }); break; }
        ok.push(c); break;
      default:
        rejected.push({ c, why: "지원하지 않는 요청이에요." });
    }
  }
  return { ok, rejected };
}

// 고객에게 보여줄 한 줄 설명
function editJosa(word, withBatchim, without) {
  const ch = String(word || "").trim().slice(-1);
  const code = ch.charCodeAt(0) - 0xac00;
  if (code < 0 || code > 11171) return withBatchim;
  return code % 28 ? withBatchim : without;
}
function describeEditCommand(c, labelOf) {
  const L0 = (k) => (labelOf ? labelOf(k) : k);
  const L = (k) => L0(k);
  const LE = (k) => `${L0(k)}${editJosa(L0(k), "을", "를")}`;
  const dir = (dx, dy) => [dy < 0 ? `위로 ${Math.abs(dy)}mm` : dy > 0 ? `아래로 ${dy}mm` : "", dx < 0 ? `왼쪽으로 ${Math.abs(dx)}mm` : dx > 0 ? `오른쪽으로 ${dx}mm` : ""].filter(Boolean).join(", ");
  const fontName = { regularGothic: "고딕", suit: "둥근고딕", myeongjo: "명조", handwriting: "손글씨" };
  const whereName = { above: "위", below: "아래", left: "왼쪽", right: "오른쪽" };
  switch (c.type) {
    case "move": return `${LE(c.target)} ${dir(c.dxMm, c.dyMm)} 옮겨요`;
    case "resize": return c.target === "logo" ? `로고 크기를 ${Math.round(c.factor * 100)}%로 ${c.factor > 1 ? "키워요" : "줄여요"}` : `${L(c.target)} 크기 ${c.fromPt != null ? `${c.fromPt}pt → ` : ""}${c.toPt}pt`;
    case "spacing": return `${L(c.target)} 자간 ${c.fromMm}mm → ${c.toMm}mm`;
    case "font": return `${L(c.target)} 글씨체를 ${fontName[c.fontId]}로 바꿔요`;
    case "place": return `${LE(c.target)} ${L(c.ref)} ${whereName[c.where]}로 옮겨요`;
    case "setText": return `${L(c.target)} 내용을 "${c.value}"(으)로 바꿔요`;
    case "background": return `배경을 ${c.color} 단색으로 바꿔요`;
    case "reset": return c.target === "all" ? "모든 위치·크기·글씨체를 원래대로 되돌려요" : `${LE(c.target)} 원래대로 되돌려요`;
    case "undo": return "방금 바꾼 것을 되돌려요";
    default: return "알 수 없는 요청";
  }
}

