    // 추가 시점에 방향을 받도록 바꿨습니다. 세로선/세로띠는 시작 위치·길이도
    // 세로축 기준(atPercent가 x, from/to가 y)으로 초기화해야 자연스럽습니다.
    const id = `deco-new-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`;
    const fresh = kind === "line"
      ? { id, kind: "line", orientation, atPercent: 50, fromPercent: 5, toPercent: 95, thicknessMm: 0.3, color: "#9CA3AF" }
      : { id, kind: "band", orientation, atPercent: 0, widthPercent: 15, color: "#E5E7EB" };
