        const textStr = k === "personName" ? personName : k === "position" ? position : introText;
        if (!textStr || !textStr.trim()) return false;
        const wMm = measureTextWidthMm(textStr.trim(), fg.pointSizePt, resolveFontFamily(FONT_FAMILY_DEFAULT).family, 400, fieldPos.letterSpacing ?? 0);
        const hMm = fg.pointSizePt * PT_TO_MM * 1.2;
        const left = fg.align === "right" ? fg.xMm - wMm : fg.align === "center" ? fg.xMm - wMm / 2 : fg.xMm;
